import sqlite3
from flask import Flask, request, redirect, url_for, session, render_template

app = Flask(__name__)
app.secret_key = 'your_secret_key'  # Changez cela par une clé secrète réelle

# Fonction pour se connecter à la base de données
def get_db_connection():
    conn = sqlite3.connect('users.db')
    conn.row_factory = sqlite3.Row
    return conn

# Route de connexion
@app.route('/login', methods=['GET', 'POST'])
def login():
    if 'username' in session:
        return "Vous êtes déjà connecté !"

    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        conn = get_db_connection()
        user = conn.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
        conn.close()

        if user is None:
            return "Nom d'utilisateur non trouvé."
        elif user['password'] == password:
            session['username'] = username
            return redirect(url_for('home'))
        else:
            return "Mot de passe incorrect."

    return render_template('login.html')

# Page d'accueil
@app.route('/home')
def home():
    if 'username' not in session:
        return redirect(url_for('login'))
    return f"Bienvenue, {session['username']} !"

# Page de déconnexion
@app.route('/logout')
def logout():
    session.pop('username', None)
    return redirect(url_for('login'))

# Création de la base de données et des utilisateurs (exemple)
@app.before_first_request
def create_tables():
    conn = get_db_connection()
    conn.execute('''
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL
        )
    ''')
    conn.execute("INSERT OR IGNORE INTO users (username, password) VALUES (?, ?)", ("admin", "admin123"))
    conn.commit()
    conn.close()

if __name__ == '__main__':
    app.run(debug=True)

